class DesktopHome extends StatefulWidget{const DesktopHome({super.key});@override State<DesktopHome> createState()=>_DesktopHomeState();}
class _DesktopHomeState extends State<DesktopHome>{final List<DeskWindow>windows=[];int next=0;bool start=false,focusActive=false,lowRam=false,batterySaver=false,cpuWarnWasShown=false,storageWarnWasShown=false;String query='';late Timer timer;static const apps=['AI Copilot','Browser','Games','Expense Tracker','Docs','Sheets','Files','Calendar','Email','Focus Mode','File Manager','Notes','Calculator','Settings','KeyMapper'];
@override void initState(){super.initState();gameBoosterAction=_boost;desktopWallpaper.value=Color(Hive.box('pocketdex_notes').get('wallpaper',defaultValue:0xff0A0A0A));DeviceResources.stats.addListener(_resourceChanged);DeviceResources.restart();ResourceSettings.instance.addListener(_settingsChanged);timer=Timer.periodic(Duration(seconds:ResourceSettings.instance.refreshSeconds),(_){if(mounted)_resourceChanged();});}
void _resourceChanged(){if(!mounted)return;final s=DeviceResources.stats.value;final total=s['ramTotal'],used=s['ramUsed'],battery=s['batteryPercent'],storage=s['storageFree'],storageTotal=s['storageTotal'];final free=total is num&&used is num?total-used:null;final freePct=DeviceResources.percent(free,total);final critical=freePct!=null&&freePct<=(ResourceSettings.instance.get('criticalRam') as num);final low=freePct!=null&&freePct<=(ResourceSettings.instance.get('lowRam') as num);if(low&&ResourceSettings.instance.get('autoLite')==true)Hive.box('resource_settings').put('liteMode',true);if(critical&&ResourceSettings.instance.get('autoMinimize')==true){final candidates=windows.where((w)=>!w.minimized).toList()..sort((a,b)=>a.id.compareTo(b.id));if(candidates.isNotEmpty)candidates.first.minimized=true;}final bp=battery is num?battery.toDouble():null;final saver=bp!=null&&bp<=(ResourceSettings.instance.get('batterySaver') as num)&&ResourceSettings.instance.get('autoBatterySaver')==true;final sp=DeviceResources.percent(storage,storageTotal);final criticalStorage=sp!=null&&sp<=(ResourceSettings.instance.get('criticalStorage') as num);final lowStorage=sp!=null&&sp<=(ResourceSettings.instance.get('lowStorage') as num);if(lowStorage&&!storageWarnWasShown){storageWarnWasShown=true;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('${criticalStorage?'CRITICAL - ':''}Low Storage ${sp.toStringAsFixed(0)}%')));}if(!lowStorage)storageWarnWasShown=false;if(low!=lowRam||saver!=batterySaver)setState((){lowRam=low;batterySaver=saver;for(final w in windows){w.lite=Hive.box('resource_settings').get('liteMode',defaultValue:false)||low||saver;}});else setState((){});if(DeviceResources.cpuWarn&&!cpuWarnWasShown){cpuWarnWasShown=true;ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('High CPU')));}if(!DeviceResources.cpuWarn)cpuWarnWasShown=false;}
void _boost(){if(!mounted)return;final before=DeviceResources.stats.value['ramUsed'];Hive.box('pocketdex_notes').put('liteMode',true);setState((){for(final w in windows){if(w.title!='Games'&&w.title!='Game Launcher')w.minimized=true;}Hive.box('pocketdex_notes').put('liteMode',true);for(final w in windows){w.lite=true;}});PaintingBinding.instance.imageCache.clear();PaintingBinding.instance.imageCache.clearLiveImages();DeviceResources.refresh().then((_){final after=DeviceResources.stats.value['ramUsed'];final diff=before is num&&after is num?(before-after).clamp(0,1<<62):null;final freed=diff==null?'N/A':'Freed ${(diff/1048576).round()} MB from XTR-M windows';if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$freed. Android does not allow killing other apps. Booster only optimizes XTR-M.')));});}
void _settingsChanged(){DeviceResources.restart();timer.cancel();timer=Timer.periodic(Duration(seconds:ResourceSettings.instance.refreshSeconds),(_){if(mounted)_resourceChanged();});if(mounted)setState((){});}
@override void dispose(){timer.cancel();DeviceResources.stats.removeListener(_resourceChanged);ResourceSettings.instance.removeListener(_settingsChanged);gameBoosterAction=null;super.dispose();}
void open(String name){setState((){start=false;final max=Hive.box('resource_settings').get('liteMode',defaultValue:false)||lowRam||batterySaver;final limit=max?ResourceSettings.instance.get('maxWindowsLite') as int:ResourceSettings.instance.get('maxWindowsNormal') as int;if(windows.where((w)=>!w.minimized).length>=limit){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Window limit reached: $limit')));return;}windows.add(DeskWindow(id:++next,title:name,child:BuiltinApp(name:name,onOpen:open,onFocusChanged:(v)=>setState(()=>focusActive=v)),lite:max));});}
@override Widget build(BuildContext context){final now=DateTime.now();return Scaffold(body:ValueListenableBuilder<Color>(valueListenable:desktopWallpaper,builder:(context,wall,_)=>LayoutBuilder(builder:(context,c)=>Stack(children:[ColoredBox(color:wall),Positioned(left:0,right:0,top:0,height:42,child:Container(color:const Color(0xff111111),padding:const EdgeInsets.symmetric(horizontal:8),child:Row(children:[Image.asset('assets/icon/logo.png',width:26,height:26,fit:BoxFit.cover),const SizedBox(width:5),const Flexible(child:Text('XTR-M',overflow:TextOverflow.ellipsis)),const SizedBox(width:6),const Expanded(child:ResourceMonitor(compact:true)),Text('${now.hour}:${now.minute.toString().padLeft(2,'0')}',style:const TextStyle(fontSize:11,color:Color(0xff8A8A8A))),if(focusActive)const Icon(Icons.timer,color:gold,size:14)]))),if(lowRam)Positioned(left:0,right:0,top:42,height:24,child:ColoredBox(color:const Color(0xff3c3020),child:Center(child:Text('Low Memory ${DeviceResources.percent((DeviceResources.stats.value['ramTotal'] as num)-(DeviceResources.stats.value['ramUsed'] as num),DeviceResources.stats.value['ramTotal'])?.toStringAsFixed(0)??'N/A'}% left',style:const TextStyle(fontSize:11,color:gold)))) ,...windows.where((w)=>!w.minimized).map((w)=>Positioned(left:w.x,top:w.y,width:w.width,height:w.height,child:DesktopWindow(key:ValueKey(w.id),window:w,onClose:()=>setState(()=>windows.removeWhere((e)=>e.id==w.id)),onMinimize:()=>setState(()=>w.minimized=true),onFront:()=>setState((){windows.remove(w);windows.add(w);})))),Positioned(left:0,right:0,bottom:0,height:50,child:Container(color:const Color(0xff111111),child:Row(children:[IconButton(onPressed:()=>setState(()=>start=!start),icon:const Icon(Icons.window_rounded,color:gold)),...['Docs','Sheets','Browser','Files','Calendar'].map((n)=>IconButton(tooltip:n,onPressed:()=>open(n),icon:Icon(_icon(n),color:const Color(0xff8A8A8A),size:18))),const Spacer(),...windows.map((w)=>IconButton(tooltip:w.title,onPressed:()=>setState(()=>w.minimized=!w.minimized),icon:Icon(_icon(w.title),color:w.minimized?const Color(0xff8A8A8A):gold,size:18)),const SizedBox(width:55))]))),AnimatedPositioned(duration:const Duration(milliseconds:220),left:8,bottom:start?56:-500,width:MediaQuery.sizeOf(context).width.clamp(280,390),height:460,child:IgnorePointer(ignoring:!start,child:_startPanel())),Positioned(right:16,bottom:62,child:SizedBox(width:48,height:48,child:FloatingActionButton(backgroundColor:gold,foregroundColor:Colors.black,onPressed:()=>open('AI Copilot'),child:const Icon(Icons.auto_awesome,size:20)))))]))));}
Widget _startPanel()=>Material(color:const Color(0xff171717),borderRadius:BorderRadius.circular(12),child:Padding(padding:const EdgeInsets.all(12),child:Column(children:[TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search,color:gold),hintText:'Search apps')),const SizedBox(height:8),Expanded(child:GridView.count(crossAxisCount:3,children:apps.where((e)=>e.toLowerCase().contains(query.toLowerCase())).map((n)=>InkWell(onTap:()=>open(n),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(_icon(n),color:gold,size:24),Text(n,textAlign:TextAlign.center,style:const TextStyle(fontSize:10))]))).toList()))])));
IconData _icon(String n)=>switch(n){'Docs'=>Icons.description,'Sheets'=>Icons.grid_on,'Browser'=>Icons.language,'Files'||'File Manager'=>Icons.folder_open,'Calendar'=>Icons.calendar_month,'Email'=>Icons.email,'Focus Mode'=>Icons.timer,'AI Copilot'=>Icons.auto_awesome,'Games'=>Icons.sports_esports,'Expense Tracker'=>Icons.account_balance_wallet,'Notes'=>Icons.note_alt,'Calculator'=>Icons.calculate,'KeyMapper'=>Icons.keyboard_alt,_=>Icons.settings};
}
class DeskWindow{DeskWindow({required this.id,required this.title,required this.child,this.lite=false}):x=30.0+(id%4)*18,y=50.0+(id%4)*16;final int id;final String title;final Widget child;double x,y,width=620,height=420;bool minimized=false,maximized=false,lite;}
